     * @param array<string, true> $affectedModels
     *
     * @return array{0: int, 1: Decimal}
     */
    private function recalculate(array $affectedModels, string $reason): array
    {
        $byModel = [];
        foreach (array_keys($affectedModels) as $key) {
            [$providerCode, $modelCode, $timestamp] = explode("\\0", $key, 3);
            $byModel[$providerCode."/".$modelCode][] = (int) $timestamp;
        }

        $repriced = 0;
        $delta = Decimal::zero();

        foreach ($byModel as $qualified => $timestamps) {
            [$providerCode, $modelCode] = explode('/', $qualified, 2);

            $provider = $this->providers->findByCode($providerCode);
            $model = null === $provider ? null : $this->models->findOne($provider, $modelCode);
            if (null === $provider || null === $model || null === $model->id()) {
                continue;
